// The mechanism tree's graph (docs/plans/mechanism-tree.md §4 D3, D5, D6; piece T1): pure, no DOM. From the coupling
// registry as the page reads it (registry-data.ts, generated by scripts/couplings.ts) it takes, for one trigger, the
// subgraph the trigger reaches; collapses each declared reflex into one loop box; finds the strongly connected
// components (Tarjan) and, inside them, the feedback edges (the edges that close a loop, drawn back toward the root);
// and returns nodes and edges in a stable order, so the same registry and trigger always draw the same picture.
//
// Why loop boxes are declared and not every component: on the six triggers' rows the circulation, the endocrine arms,
// the chemoreflex, the brain's perfusion and the drug model's flow-dependent PK all close on one another through MAP
// and cardiac output, so Tarjan finds one component of 57 nodes (propofol: 57 of the 76 it reaches). Drawn as one box
// that would hide SVR, the venous volume and MAP inside it. So the reflex controllers are the boxes (the baroreflex:
// its sensed pressure, set point, sympathetic and vagal errors and its gains, D5's "MAP → error → sympathetic outflow"),
// the effectors they set and the plant stay nodes, and the loops the components hold are drawn as feedback edges.

/** registry types, as packages/engine-core/src/couplings/types.ts defines them (the demo imports the engine's root only). */
export type NodeKind = 'trigger' | 'state' | 'effector' | 'observable';
export type EdgeClass = 'SOURCED' | 'FIT' | 'ENG' | 'ABSENT' | 'UNTAGGED';
export type Sign = '+' | '−' | '±';
export type Form = 'factor' | 'term' | 'gain' | 'threshold' | 'state';

export interface TreeConst { name: string; value?: string; unit?: string; source: string }
export interface TreeRow {
  id: string;
  module: string;
  from: readonly string[];
  to: string;
  sign: Sign;
  form: Form;
  cls: EdgeClass;
  absent?: string;
  delay?: string;
  tau?: string;
  saturation?: string;
  blockedBy?: string;
  consts: readonly TreeConst[];
  note: string;
}
export interface TreeNodeDecl { path: string; kind: NodeKind; label?: string; absent?: string }
export interface TreeData {
  triggers: readonly { path: string; label: string }[];
  nodes: readonly TreeNodeDecl[];
  rows: readonly TreeRow[];
}

/** The class an edge is drawn with. NONE: a row that names no constant (a hand-off, or numbers inline in the code): a
 *  pass-through with no honesty claim, drawn plain. R1 computes it as UNTAGGED; the orchestrator ruled it its own class
 *  for R2, so the page does not call a pass-through "untagged". */
export type DrawClass = EdgeClass | 'NONE';
export const drawClass = (r: TreeRow): DrawClass => (r.cls === 'UNTAGGED' && r.consts.length === 0 ? 'NONE' : r.cls);
/** Merged rows draw as the most cautious of their classes: a fitted row is never hidden behind a sourced one. */
const CAUTION: readonly DrawClass[] = ['FIT', 'ENG', 'UNTAGGED', 'SOURCED', 'NONE'];

/** A reflex controller drawn as one loop box (D5). */
export interface LoopDecl { id: string; label: string; members: (path: string) => boolean }
export const LOOPS: readonly LoopDecl[] = [
  { id: 'loop.baroreflex', label: 'Baroreflex', members: (p) => p.startsWith('hemo.circ.baro.') || p === 'circ.baro.gains' },
  { id: 'loop.chemoreflex', label: 'Chemoreflex', members: (p) => p.startsWith('hemo.circ.chemo.') },
];

/** The forward subgraph: the nodes the trigger reaches (breadth first, rows in registry order) and one edge per
 *  reached `from` node of each row whose `from` the trigger reaches. */
export interface Subgraph {
  root: string;
  nodes: string[];
  edges: { from: string; to: string; row: TreeRow }[];
}
export function forward(data: TreeData, trigger: string): Subgraph {
  const out = new Map<string, { to: string; row: TreeRow }[]>();
  for (const row of data.rows) for (const f of row.from) (out.get(f) ?? out.set(f, []).get(f)!).push({ to: row.to, row });
  const seen = new Set([trigger]);
  const nodes = [trigger];
  for (let i = 0; i < nodes.length; i++)
    for (const { to } of out.get(nodes[i] as string) ?? []) if (!seen.has(to)) seen.add(to), nodes.push(to);
  const edges = data.rows.flatMap((row) => row.from.filter((f) => seen.has(f)).map((from) => ({ from, to: row.to, row })));
  return { root: trigger, nodes, edges };
}

export interface TreeNode {
  id: string;
  kind: NodeKind | 'loop';
  label: string;
  /** The engine key (a loop: its members' keys). */
  keys: string[];
  /** An ABSENT node's audit id. */
  absent?: string;
}
export interface TreeEdge {
  from: string;
  to: string;
  rows: TreeRow[];
  cls: DrawClass;
  /** An ABSENT edge's audit id (absent and present rows are never merged). */
  absent?: string;
  /** Closes a loop: drawn back toward the root. */
  feedback: boolean;
}
export interface Tree {
  root: string;
  nodes: TreeNode[];
  edges: TreeEdge[];
  /** Strongly connected components with more than one node, largest first. */
  loops: string[][];
  /** Rows inside a loop box (both ends in it), by loop id. */
  inner: Map<string, TreeRow[]>;
}

/** Tarjan's strongly connected components, iterating nodes and out-edges in the given order; also the feedback edges:
 *  the edges of a depth-first search from `root` that reach a node on the current path (each closes a cycle; without
 *  them the graph is acyclic). */
export function components(nodes: readonly string[], edges: readonly { from: string; to: string }[], root: string): { sccs: string[][]; feedback: Set<number> } {
  const out = new Map<string, number[]>();
  edges.forEach((e, i) => (out.get(e.from) ?? out.set(e.from, []).get(e.from)!).push(i));
  const index = new Map<string, number>();
  const low = new Map<string, number>();
  const stack: string[] = [];
  const onStack = new Set<string>();
  const onPath = new Set<string>();
  const sccs: string[][] = [];
  const feedback = new Set<number>();
  let n = 0;
  const visit = (v: string): void => {
    index.set(v, n), low.set(v, n++), stack.push(v), onStack.add(v), onPath.add(v);
    for (const i of out.get(v) ?? []) {
      const w = (edges[i] as { to: string }).to;
      if (!index.has(w)) visit(w), low.set(v, Math.min(low.get(v)!, low.get(w)!));
      else if (onStack.has(w)) low.set(v, Math.min(low.get(v)!, index.get(w)!));
      if (onPath.has(w)) feedback.add(i);
    }
    onPath.delete(v);
    if (low.get(v) === index.get(v)) {
      const c: string[] = [];
      let w: string;
      do (w = stack.pop() as string), onStack.delete(w), c.push(w);
      while (w !== v);
      sccs.push(c);
    }
  };
  for (const v of [root, ...nodes]) if (!index.has(v)) visit(v);
  return { sccs, feedback };
}

/** A node's words: the glossary's label where it has one (`gloss`), else the registry's declared label, else the key. */
export type Labeller = (path: string) => string | null;

/** The tree one trigger sets off, ready for layout (D3, D5): nodes in discovery order, merged edges in registry order. */
export function mechanismTree(data: TreeData, trigger: string, gloss: Labeller = () => null, loops: readonly LoopDecl[] = LOOPS): Tree {
  const sub = forward(data, trigger);
  const decl = new Map(data.nodes.map((d) => [d.path, d]));
  const loopOf = (p: string): LoopDecl | undefined => loops.find((l) => l.members(p));
  const idOf = (p: string): string => loopOf(p)?.id ?? p;

  const nodes: TreeNode[] = [];
  const byId = new Map<string, TreeNode>();
  for (const p of sub.nodes) {
    const loop = loopOf(p);
    const id = loop?.id ?? p;
    const known = byId.get(id);
    if (known) {
      known.keys.push(p);
      continue;
    }
    const d = decl.get(p);
    const node: TreeNode = loop
      ? { id, kind: 'loop', label: loop.label, keys: [p] }
      : { id, kind: d?.kind ?? 'state', label: gloss(p) ?? d?.label ?? p, keys: [p], ...(d?.absent ? { absent: d.absent } : {}) };
    nodes.push(node), byId.set(id, node);
  }

  const merged = new Map<string, TreeEdge>();
  const inner = new Map<string, TreeRow[]>();
  for (const e of sub.edges) {
    const from = idOf(e.from);
    const to = idOf(e.to);
    if (from === to) {
      const list = inner.get(from) ?? inner.set(from, []).get(from)!;
      if (!list.includes(e.row)) list.push(e.row);
      continue;
    }
    const key = `${from}\u0000${to}\u0000${e.row.absent ? 'A' : 'P'}`;
    const m = merged.get(key);
    if (m) {
      if (!m.rows.includes(e.row)) m.rows.push(e.row);
    } else merged.set(key, { from, to, rows: [e.row], cls: 'NONE', ...(e.row.absent ? { absent: e.row.absent } : {}), feedback: false });
  }
  const edges = [...merged.values()];
  for (const e of edges) {
    if (e.absent) e.cls = 'ABSENT';
    else {
      const cs = e.rows.map(drawClass);
      e.cls = CAUTION.find((c) => cs.includes(c)) ?? 'NONE';
    }
  }
  const { sccs, feedback } = components(nodes.map((x) => x.id), edges, trigger);
  for (const i of feedback) (edges[i] as TreeEdge).feedback = true;
  const loopsFound = sccs.filter((c) => c.length > 1).sort((a, b) => b.length - a.length);
  return { root: trigger, nodes, edges, loops: loopsFound, inner };
}
